/** Pack index by team number, i.e. `shotType >> 2` for the pairs. */
export const th08PlayerAnmPack = (index: number): PlayerAnmPackData | null =>
  TH08_PLAYER_ANM_PACKS[index] ?? null;

/**
 * Atlas cell key the renderer registers player art under, matching
 * `registerTH08PlayerSprites`'s naming so shots and ships share pages.
 */
export const th08PlayerCellKey = (pack: number, sprite: number): string | null => {
  const p = TH08_PLAYER_ANM_PACKS[pack];
  const r = p?.rects[sprite] ?? null;
  return r ? `th08:player:${p!.name}_t${r.tex}:${sprite}` : null;
};
